# ==============================================================================# IOTEC MISSION CONTROL# 011_MISSION_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)cur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS missions(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    title TEXT,    description TEXT,    status TEXT,    priority TEXT,    owner TEXT)""")conn.commit()def nova_missao(        titulo,        descricao="",        prioridade="NORMAL",        responsavel="MAESTRO"):    cur.execute(        """        INSERT INTO missions(            created_at,            title,            description,            status,            priority,            owner        )        VALUES(?,?,?,?,?,?)        """,        (            datetime.now().isoformat(),            titulo,            descricao,            "OPEN",            prioridade,            responsavel        )    )    conn.commit()    return cur.lastrowidmission_id = nova_missao(    "InicializaÃ§Ã£o do Mission Control",    "Primeira missÃ£o criada automaticamente.",    "HIGH")cur.execute("SELECT COUNT(*) FROM missions")total = cur.fetchone()[0]print("=" * 80)print("MISSION ENGINE")print("=" * 80)print(f"MISSION ID.....: {mission_id}")print(f"TOTAL..........: {total}")print("=" * 80)conn.close()

